size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate)
{
  size_t bytes_written = 0;
  MagickBooleanType monochrome = MagickFalse;
  unsigned int y;
  ssize_t count;
  unsigned char *pixels = NULL;
  size_t scanline_size = 0;
  size_t compressed_size = 0;
  unsigned char *compressed_pixels = NULL;

  if (image->depth == 1)
    monochrome = MagickTrue;

  scanline_size = image->columns * (monochrome ? 1 : 3);
  if (psd_info->compression == RLECompression)
  {
    compressed_pixels = AcquireMemory(scanline_size + 257);
    if (compressed_pixels == (unsigned char *) NULL)
    {
      ThrowMagickException(&image->exception, GetMagickModule(), ResourceLimitError, "MemoryAllocationFailed", "`%s' (%lu x %lu)", image->filename, (unsigned long) image->columns, (unsigned long) image->rows);
      return 0;
    }
  }

  for (y = 0; y < (unsigned int) image->rows; y++)
  {
    count = ExportImagePixelData(image, compact_pixels, quantum_type, MagickFalse);
    if (count < 0)
      break;

    if (psd_info->compression == RLECompression)
    {
      compressed_size = RLECompress(compact_pixels, compressed_pixels, (size_t) scanline_size, image->columns);
      count = WriteBlob(image, compressed_size, compressed_pixels);
    }
    else
    {
      count = WriteBlob(image, (size_t) scanline_size, compact_pixels);
    }

    bytes_written += (size_t) count;
  }

  if (psd_info->compression == RLECompression)
    RelinquishMemory(compressed_pixels);

  return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate) {
  size_t number_pixels = 0;
  size_t number_channels = 1;
  size_t bytes_written = 0;
  unsigned char *pixels = NULL;
  size_t row;
  size_t length;

  if (image->depth > 8)
    number_channels = 4;

  pixels = (unsigned char *) AcquireMemory(image->columns * number_channels);

  for (row = 0; row < image->rows; row++) {
    ExportPixelPacket(image, &pixels[row * image->columns * number_channels],
                      image->columns, 1, quantum_type);

    if (psd_info->compression == 1) {
      length = CompressPSDRow(pixels + row * image->columns * number_channels,
                              image->columns, number_channels, compact_pixels);
      bytes_written += length;
      size_offset += length;
    }
    else {
      length = image->columns * number_channels;
      (void) CopyMagickMemory(compact_pixels, pixels + row * image->columns * number_channels, length);
      bytes_written += length;
      size_offset += length;
    }
  }

  if (pixels)
    pixels = RelinquishMemory(pixels);

  return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate)
{
  size_t bytes_written = 0;
  size_t rows = image->rows;
  size_t columns = image->columns;
  size_t length;
  size_t y;
  MagickBooleanType status;
  unsigned char *pixels = (unsigned char *) AcquireQuantumMemory((size_t) columns, sizeof(*pixels));
  MagickOffsetType offset = size_offset;

  if (pixels == (unsigned char *) NULL)
    return 0;

  if (psd_info->monochrome != MagickFalse)
  {
    for (y = 0; y < rows; y++)
    {
      length = 0;
      status = ExportQuantumPixels(image, (Cache) NULL, (PixelInfo *) NULL, quantum_type, compact_pixels + length, &length);
      if (status == MagickFalse)
        break;
      offset += WriteBlobMemory(image, length, compact_pixels + offset);
      bytes_written += length;
    }
  }
  else
  {
    for (y = 0; y < rows; y++)
    {
      length = 0;
      status = ExportQuantumPixels(image, (Cache) NULL, (PixelInfo *) NULL, quantum_type, pixels, &length);
      if (status == MagickFalse)
        break;
      offset += WriteBlobMemory(image, length, compact_pixels + offset);
      bytes_written += length;
    }
  }

  if (separate != MagickFalse)
  {
    for (y = 0; y < rows; y++)
    {
      length = 0;
      status = ExportQuantumPixels(image, (Cache) NULL, (PixelInfo *) NULL, quantum_type, compact_pixels + length, &length);
      if (status == MagickFalse)
        break;
      offset += WriteBlobMemory(image, length, compact_pixels + offset);
      bytes_written += length;
    }
  }

  compact_pixels = (unsigned char *) RelinquishMagickMemory(compact_pixels);
  pixels = (unsigned char *) RelinquishMagickMemory(pixels);

  return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate)
{
  size_t
    bytes,
    count;

  register ssize_t
    x;

  MagickBooleanType
    status;

  register Quantum
    *p;

  size_t
    total_bytes = 0;

  unsigned char
    *pixels = NULL;

  MagickOffsetType
    offset = size_offset;

  ssize_t
    y;

  size_t
    height = image->rows;

  size_t
    width = image->columns;

  MagickBooleanType
    is_monochrome = (psd_info->depth == 1);

  count = width;
  bytes = count * sizeof(*pixels);

  pixels = (unsigned char *) AcquireMemory(bytes);

  if (pixels == (unsigned char *) NULL)
    return 0;

  p = GetAuthenticPixels(image, 0, 0, width, 1, (CacheView *) NULL);

  if (p == (Quantum *) NULL)
  {
    RelinquishMemory(pixels);
    return 0;
  }

  for (y = 0; y < (ssize_t) height; y++)
  {
    ExportQuantumPixels(image, (CacheView *) NULL, quantum_type, count, pixels, (QuantumInfo *) NULL);
    if (is_monochrome)
    {
      for (x = 0; x < (ssize_t) count; x++)
        pixels[x] = (unsigned char) (QuantumRange - (MagickRealType) p[x]);
    }

    if (psd_info->compression == RLECompression)
    {
      size_t
        compressed_length;

      unsigned char
        *compressed_data = RLECompress(pixels, count, &compressed_length);

      if (compressed_data != (unsigned char *) NULL)
      {
        count = WriteBlobMemory(image, compressed_length, compressed_data);
        total_bytes += count;
        RelinquishMemory(compressed_data);
      }
    }
    else
    {
      count = WriteBlob(image, bytes, pixels);
      total_bytes += count;
    }

    if (y != (ssize_t) (height - 1))
    {
      p += GetPixelChannels(image);
      SyncAuthenticPixels(image, (CacheView *) NULL);
      p = GetAuthenticPixels(image, 0, y + 1, width, 1, (CacheView *) NULL);
    }
  }

  RelinquishMemory(pixels);
  return total_bytes;
}

